(7480649, 1190018, 112739, '<td valign="top">One individual who opened himself up for nourishment. I''m sure there is more here than my eye can unscramble right now.</td>', 'One individual who opened himself up for nourishment. I''m sure there is more here than my eye can unscramble right now.', '2016-11-03 11:49:32.000000', NULL, 1),
(7480680, 1190018, 163081, '<td valign="top">Sometimes I think you''re an alien. Where the hell you find all that inspiration to each time come with such a great concept. A 9 from me.</td>', 'Sometimes I think you''re an alien. Where the hell you find all that inspiration to each time come with such a great concept. A 9 from me.', '2016-11-03 13:54:02.000000', NULL, 1),
(7480706, 1189927, 16148, '<td valign="top">Lovely theater for the eyes and mind.  The shrub haphazardly planted at the bottom of the staircase. The eye on the mailbox.  The subtle diamond pattern from a security fence.  Maybe this house, once a home, will be demolished soon.  Your photograph, like Dylan''s lyrics, has me digging deeper and uncertain.  Thanks</td>', 'Lovely theater for the eyes and mind.  The shrub haphazardly planted at the bottom of the staircase. The eye on the mailbox.  The subtle diamond pattern from a security fence.  Maybe this house, once a home, will be demolished soon.  Your photograph, like Dylan''s lyrics, has me digging deeper and uncertain.  Thanks', '2016-11-03 16:16:26.000000', NULL, 1),
(7480707, 1189849, 16148, '<td valign="top">This is a stretch.  Nice tribute!  Thanks</td>', 'This is a stretch.  Nice tribute!  Thanks', '2016-11-03 16:17:50.000000', NULL, 1),
(7480728, 1190033, 16148, '<td valign="top">I enjoyed this humble photograph.  Delightful!</td>', 'I enjoyed this humble photograph.  Delightful!', '2016-11-03 19:44:22.000000', NULL, 1),
(7480741, 1190017, 16148, '<td valign="top">A hobo''s dream comes true.  Nothing like homemade pie cooling on a windowsill.  I imagine Bob would appreciate this and all the stories it offers.<br/> <br/>"the unwashed phenomenon, the original vagabond" - Joan Baez</td>', 'A hobo''s dream comes true.  Nothing like homemade pie cooling on a windowsill.  I imagine Bob would appreciate this and all the stories it offers. "the unwashed phenomenon, the original vagabond" - Joan Baez', '2016-11-03 21:27:37.000000', NULL, 1),
(7480879, 1189798, 159196, '<td valign="top">Beautiful in every way!</td>', 'Beautiful in every way!', '2016-11-04 03:46:13.000000', NULL, 1),
(7480880, 1190018, 159196, '<td valign="top">Magnificent on so many levels - you captured the entire song in one photograph. As always, you are an artist!</td>', 'Magnificent on so many levels - you captured the entire song in one photograph. As always, you are an artist!', '2016-11-04 03:52:17.000000', NULL, 1),
(7481001, 1190037, 94815, '<td valign="top">Challenging choice to try and depict this simplest, most surreal of his songs. It''s a tune and one line of lyrics that will never leave even my addled memory, and this thoughtful montage is an aptly fitting accompaniment that I think will linger as well.</td>', 'Challenging choice to try and depict this simplest, most surreal of his songs. It''s a tune and one line of lyrics that will never leave even my addled memory, and this thoughtful montage is an aptly fitting accompaniment that I think will linger as well.', '2016-11-04 16:34:03.000000', NULL, 1),
